set body = '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A query is a public listening initiative: up to five ordered questions, published as its own page or embedded in a Grove article, with the answers coming back to you here."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Create a query"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"From the query list, select "},{"type":"text","text":"New query","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fill in an internal title (for your own list), a public title (what a listener sees), and a public introduction saying why you''re asking and what you''ll do with the answers. Select "},{"type":"text","text":"Create query","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You land on the new query''s Questions tab."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Add questions"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fill in a question''s prompt, and optionally public guidance, internal context (staff-only), a maximum answer length, and whether it''s required."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Add question","marks":[{"type":"bold"}]},{"type":"text","text":". Repeat for up to five questions."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reorder or duplicate a question with the buttons on its card, or remove one — before anyone has answered."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Configure settings"}]},{"type":"paragraph","content":[{"type":"text","text":"The Settings tab covers everything about how the query behaves, separate from its questions:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Participant information","marks":[{"type":"bold"}]},{"type":"text","text":" — which details (name, city, email, phone, a free-text note) to ask for, each set to don''t ask, optional, or required. Asked once for the whole submission, never per question."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Consent and attribution","marks":[{"type":"bold"}]},{"type":"text","text":" — three separate questions that stay separate on the record: permission to be contacted, permission to be named, and the option to request anonymity. Permission to be contacted is not permission to be named, and asking for anonymity is neither. The consent terms text itself is required and is recorded with the submission at the moment it''s accepted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Opens and closes dates","marks":[{"type":"bold"}]},{"type":"text","text":" — both optional; leaving them blank means the query opens as soon as you select "},{"type":"text","text":"Open for responses","marks":[{"type":"bold"}]},{"type":"text","text":" and stays open until you close it. Someone already recording when a close date passes may still finish and submit."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Transcription","marks":[{"type":"bold"}]},{"type":"text","text":" — manual (send answers after reviewing them) or automatic (every answer is queued the moment it''s submitted, then sent in one click from the Submissions tab)."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Publish it"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the query''s header — visible from any tab — select "},{"type":"text","text":"Open for responses","marks":[{"type":"bold"}]},{"type":"text","text":". Until then, the public link and embed code don''t work, even for someone who already has them."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Go to the Share tab for a "},{"type":"text","text":"Copy link","marks":[{"type":"bold"}]},{"type":"text","text":" button for the standalone public page, and a "},{"type":"text","text":"Copy embed code","marks":[{"type":"bold"}]},{"type":"text","text":" button for a ready-made Grove iframe snippet — paste it into a Grove Responsive Embed element unchanged. If you add or remove questions later, copy the embed code again."}]}]}]},{"type":"figure","attrs":{"mediaId":"75a53aef-70d8-4f39-879d-d04253d87bff","alt":"A query''s Share tab, with the Public link and Grove embed code cards and their Copy buttons.","caption":"The Share tab, once a query is ready to publish."}},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Good to know"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Preview","marks":[{"type":"bold"}]},{"type":"text","text":" (always available, even on a draft) to walk through the query as a participant would — nothing is submitted."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Once a query has submissions, question wording stays editable, but removing or reordering questions is no longer offered — an answer keeps the exact wording it was asked under."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The header''s action changes with status: open queries offer "},{"type":"text","text":"Close query","marks":[{"type":"bold"}]},{"type":"text","text":" (stops new responses; anyone already recording can still finish); closed ones offer "},{"type":"text","text":"Open for responses","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"Archive query","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A query can be deleted only before it has any submissions, from the Settings tab. Once a submission exists, archiving — which keeps every response, answer, and transcription link — is how you finish with it."}]}]}]}]}'::jsonb,
